const APP_ENVIRONMENTS = ["local", "test", "production"] as const;

export type AppEnvironment = (typeof APP_ENVIRONMENTS)[number];

export type RuntimeEnvironment = {
  name: AppEnvironment;
  baseUrl: URL;
};

function required(name: string): string {
  const value = process.env[name]?.trim();
  if (!value) throw new Error(`Missing required environment variable: ${name}`);
  return value;
}

function parseHttpUrl(name: string, raw: string): URL {
  let value: URL;
  try {
    value = new URL(raw);
  } catch {
    throw new Error(`${name} must be a valid absolute URL`);
  }
  if (
    value.protocol !== "https:" &&
    value.hostname !== "localhost" &&
    value.hostname !== "127.0.0.1"
  ) {
    throw new Error(`${name} must use HTTPS outside local development`);
  }
  return value;
}

export function getRuntimeEnvironment(): RuntimeEnvironment {
  const rawName = required("APP_ENV");
  if (!APP_ENVIRONMENTS.includes(rawName as AppEnvironment)) {
    throw new Error("APP_ENV must be local, test, or production");
  }

  const name = rawName as AppEnvironment;
  const baseUrl = parseHttpUrl("APP_BASE_URL", required("APP_BASE_URL"));

  if (name === "test") {
    const productionUrl = parseHttpUrl("PRODUCTION_BASE_URL", required("PRODUCTION_BASE_URL"));
    if (baseUrl.origin === productionUrl.origin) {
      throw new Error("Test environment must not use the production URL");
    }
  }

  if (name === "production" && process.env.NODE_ENV !== "production") {
    throw new Error("Production APP_ENV requires a production Node.js runtime");
  }

  return { name, baseUrl };
}
